# Add the new homepage CSS once, immediately before the site stylesheet closes.
anchor = "\n`;\nfunction claudeInstallUrl()"
if anchor not in s:
    raise SystemExit('siteCss closing anchor not found')
if '/* Interactive homepage experience */' not in s:
    s = s.replace(anchor, HOME_CSS + anchor, 1)

